def estimate2(case, mode='p2c', c_fixed=1.4, p_fixed=2.0, cb=(-.7,.7), fitp=False):
    kap=case['kappa']; sig=case['sigma']; x=case['x']; t=case['t']; y=case['y']
    A=np.sin(np.pi*np.outer(x,kk))*np.exp(-kap*np.pi**2*np.outer(t,kk**2))
    m=len(y)
    def nll(logc,p):
        var=(10**logc*kk**-p)**2
        C=A@(var[:,None]*A.T); C[np.diag_indices(m)]+=sig*sig
        try: L=np.linalg.cholesky(C)
        except np.linalg.LinAlgError: return 1e9
        alpha=np.linalg.solve(L,y)
        return .5*np.dot(alpha,alpha)+np.sum(np.log(np.diag(L)))
    if mode=='fixed': c=c_fixed; p=p_fixed
    elif mode=='estc':
        r=minimize_scalar(lambda lc:nll(lc,p_fixed),bounds=cb,method='bounded'); c=10**r.x; p=p_fixed
    elif mode=='estcp':
        best=None
        for p in np.linspace(1.5,2.5,9):
            r=minimize_scalar(lambda lc:nll(lc,p),bounds=cb,method='bounded')
            if best is None or r.fun<best[0]: best=(r.fun,p,10**r.x)
        _,p,c=best
    elif mode=='oracle':
        # c matching normalized truth to p2: sqrt(2/sum a^2 k^4)
        p=2.; c=np.sqrt(2/np.sum(case['a']**2*kk**4))
    var=(c*kk**-p)**2
    M=A.T@A+np.diag(sig*sig/var)
    a=np.linalg.solve(M,A.T@y)
    return a,c,p

if __name__=='__main__':
    rng=np.random.default_rng(42)
